\label{app:metrics_dist}
In this section, we introduce two widely used metrics for quantifying differences between probability distributions: the total variation (TV) distance and the Hellinger distance. 

Let $\mu_1$ and $\mu_2$ be two probability measures with corresponding probability density functions $f_1(x)$ and $f_2(x)$. The total variation distance between $\mu_1$ and $\mu_2$ is defined as:
\begin{equation}
d_{TV}(\mu_1,\mu_2) := \frac{1}{2}\int \big \lvert f_1(x) - f_2(x) \big \rvert dx.
\end{equation}
The Hellinger distance between $\mu_1$ and $\mu_2$ is defined by:
\begin{equation}
d_{H}(\mu_1,\mu_2) := \sqrt{\frac{1}{2}\int \left( \sqrt{f_1(x)} - \sqrt{f_2(x) }\right)^2 dx}.
\end{equation}

\label{app:proof_thm}
Let $q_k^*(X_k,\theta)$ denote the resulting joint posterior distribution $\pdense(X_k,\theta \mid \Y_k)$ when the previous joint posterior $\pdense(X_{k-1},\theta \mid \Y_{k-1})$ is replaced with its approximation $q_{k-1}(X_{k-1},\theta)$. The following theorem established in our previous work~\cite{wang_gorodetsky_2025_lipschitz_stability} is used for the proof of Theorem~\ref{thm:error_bound}.
\begin{theorem}[Theorem 16 in~\cite{wang_gorodetsky_2025_lipschitz_stability}]
\label{thm:learning_bound}
For any step $k \geq 2$, given a sequence of data $\Y_k=(y_1,y_2,\cdots,y_k)$, suppose that for any step $i \in [2,k]$, we have
\begin{equation}
\bar{C}(y_i;i) := \sup_{X_{i-1},\theta}\int p(y_i \mid X_i,\theta)p(X_i \mid X_{i-1},\theta)dX_i < \infty.
\label{ieq:assumption}
\end{equation}
The total variation distance between $p(X_k,\theta \mid \Y_k)$ and $q_k(X_k,\theta)$, namely $d_{TV}\left(p(X_k,\theta \mid \Y_k), q_k(X_k,\theta)\right)$, satisfies:
\begin{align}
d_{TV}\left(p(X_k,\theta \mid \Y_k), q_k(X_k,\theta)\right) &\leq \sum_{j=1}^{k-1}\frac{\prod_{i=j+1}^k\bar{C}(y_i;i)}{p(\Y_{j+1:k}\mid \Y_{1:j})}d_{TV}\left(q_j, q_j^*\right) + d_{TV}\left(q_k, q_k^*\right).
\end{align}
The Hellinger distance between $p(X_k,\theta \mid \Y_k)$ and $q_k(X_k,\theta)$, namely $d_{H}(p(X_k,\theta \mid \Y_k), q_k(X_k,\theta))$, satisfies:
\begin{align}
d_{H}(p(X_k,\theta \mid \Y_k), q_k(X_k,\theta)) &\leq \sum_{j=1}^{k-1}\frac{2^{(k-j)}\prod_{i=j+1}^k\sqrt{\bar{C}(y_i;i)}}{\sqrt{p(\Y_{j+1:k}\mid \Y_{1:j})}}d_{H}\left(q_j, q_j^*\right) + d_{H}\left(q_k, q_k^*\right).
\end{align}

\end{theorem}
We now prove Theorem~\ref{thm:error_bound}.
\begin{proof} 
We begin by confirming that the assumption in Theorem~\ref{thm:learning_bound} holds.

For any $i \in [2, k]$, if $\inf_{\theta} |\Gamma(\theta)| = \tilde{C} > 0$, then
\begin{align*}
\pdense(y_i \mid X_i,\theta) &= \pdense_{\mathcal{N}}(y_i ; h(X_i;\theta), \Gamma(\theta)) = (2\pi)^{-\frac{r}{2}}\big \lvert \Gamma(\theta)\big \rvert^{-\frac{1}{2}} \exp \left(-\frac{1}{2}\left(y_i - h(X_i;\theta)\right)^T\Gamma(\theta)^{-1}\left(y_i - h(X_i;\theta)\right)\right) \nonumber \\
&\leq (2\pi)^{-\frac{r}{2}} \big \lvert \Gamma(\theta) \big \rvert^{-\frac{1}{2}} \leq (2\pi)^{-\frac{r}{2}}\tilde{C}^{-\frac{1}{2}}.
\end{align*}
Thus,
\begin{align}
\bar{C}(y_i;i) &=\sup_{X_{i-1},\theta}\int p(y_i \mid X_i,\theta)p(X_i \mid X_{i-1},\theta)dX_i \nonumber \\
&\leq (2\pi)^{-\frac{r}{2}}\tilde{C}^{-\frac{1}{2}}\sup_{X_{i-1},\theta}\int p(X_i \mid X_{i-1},\theta)dX_i  \nonumber \\
&= (2\pi)^{-\frac{r}{2}}\tilde{C}^{-\frac{1}{2}} < \infty,
\label{ieq:vi:type1:C}
\end{align}
and hence the assumption of Theorem~\ref{thm:learning_bound} is satisfied.

We now derive an upper bound on the total variation distance between $q_i(X_i,\theta)$ and $q^*_i(X_i,\theta)$. Note that $q^*_i(X_i,\theta)$ can be written as 
\begin{equation*}
q^*_i(X_i,\theta) = \rho_i^*(X_i\mid \theta)\nu^*_i(\theta).
\end{equation*}
The KL divergence of the distribution $q_i$ with respect to the distribution $q^*_i$ can be written as
\begin{align}
\KL(q_i \lVert q^*_i) &= \E_{(X_i,\theta) \sim q_i(\cdot)}\left[\log \left(\frac{q_i(X_i,\theta)}{q^*_i(X_i,\theta)}\right) \right] \nonumber \\
&= \E_{(X_i,\theta) \sim q_i(\cdot)}\left[\log \left(\frac{\rho_i(X_i \mid \theta)\nu_i(\theta)}{\rho^*_i(X_i \mid \theta)\nu^*_i(\theta)}\right)\right] \nonumber \\
&= \E_{(X_i,\theta) \sim q_i(\cdot)}\left[\log \left(\frac{\rho_i(X_i \mid \theta)}{\rho^*_i(X_i \mid \theta)}\right)\right] + \E_{(X_i,\theta) \sim q_i(\cdot)}\left[\log \left(\frac{\nu_i(\theta)}{\nu^*_i(\theta)}\right)\right].
\label{eq:kl}
\end{align}
The first term on the right hand side in Equation~\eqref{eq:kl} can be expressed as
\begin{equation}
\E_{(X_i,\theta) \sim q_i(\cdot)}\left[\log \left(\frac{\rho_i(X_i \mid \theta)}{\rho^*_i(X_i \mid \theta)}\right)\right] = \E_{\theta \sim \nu_i(\cdot)}\left[\E_{X_i \sim \rho_i(\cdot \mid \theta)}\left[\log \left(\frac{\rho_i(X_i \mid \theta)}{\rho^*_i(X_i \mid \theta)}\right)\right]\right] = \E_{\theta \sim \nu_i(\cdot)}\left[\KL\left(\rho_i(\cdot \mid \theta) \lVert \rho_i^*(\cdot \mid \theta) \right) \right].
\label{eq:term1_kl}
\end{equation}
Since the term $\log \left(\frac{\nu_i(\theta)}{\nu^*_i(\theta)}\right)$ does not depend on $X_i$, the second term on the right hand side in Equation~\eqref{eq:kl} satisfies
\begin{equation}
\E_{(X_i,\theta) \sim q_i(\cdot)}\left[\log \left(\frac{\nu_i(\theta)}{\nu^*_i(\theta)}\right)\right] = \E_{\theta \sim \nu_i(\cdot)}\left[\log \left(\frac{\nu_i(\theta)}{\nu^*_i(\theta)}\right)\right] = \KL\left(\nu_i \lVert \nu_i^*\right).
\label{eq:term2_kl}
\end{equation}
Plugging Equations~\eqref{eq:term1_kl} and ~\eqref{eq:term2_kl} into Equation~\eqref{eq:kl} yields
\begin{align}
\KL\left(q_i \lVert q^*_i \right) = \E_{\theta \sim \nu_i(\cdot)}\left[\KL\left(\rho_i(\cdot \mid \theta) \lVert \rho_i^*(\cdot \mid \theta) \right) \right] +\KL\left(\nu_i \lVert \nu_i^*\right).
\label{eq:kl_rewritten}
\end{align}
Therefore, we get
\begin{align}
d_{TV}(q_i,q_i^*) & \leq \frac{1} {\sqrt{2}}\sqrt{\KL\left(q_i \lVert q^*_i\right)} \nonumber \\
&= \frac{1}{\sqrt{2}}\sqrt{\E_{\theta \sim \nu_i(\cdot)}\left[\KL\left(\rho_i(\cdot\mid \theta) \lVert \rho_i^*(\cdot \mid \theta) \right) \right] +\KL\left(\nu_i \lVert \nu_i^*\right)}.
\label{ieq:vi:type1:tv_approx}
\end{align}
An analogous inequality holds for the Hellinger distance:
\begin{align}
d_{H}(q_i,q_i^*) & \leq \frac{1}{\sqrt{2}}\sqrt{\KL\left(q_i \lVert q^*_i\right)} \nonumber \\
& = \frac{1}{\sqrt{2}}\sqrt{\E_{\theta \sim \nu_i(\cdot)}\left[\KL\left(\rho_i(\cdot \mid \theta) \lVert \rho_i^*(\cdot \mid \theta) \right) \right] +\KL\left(\nu_i \lVert \nu_i^*\right)}.
\label{ieq:vi:type1:H_approx}
\end{align}
Lastly, combining Theorem~\ref{thm:learning_bound} with
Equations~\eqref{ieq:vi:type1:C}, \eqref{ieq:vi:type1:tv_approx}, and \eqref{ieq:vi:type1:H_approx}
completes the proof of Theorem~\ref{thm:error_bound}.
\end{proof}

\label{app:proof_thm_linear}
The following theorem established in our prior work~\cite{wang_gorodetsky_2025_lipschitz_stability} is used for the proof of Theorem~\ref{thm:error_bound_linear}.
\begin{theorem}[Theorem 16 in~\cite{wang_gorodetsky_2025_lipschitz_stability}]
\label{thm:learning_bound_z}
For any step $k \geq 2$, given a sequence of data $\Y_k=(y_1,y_2,\cdots,y_k)$, suppose that for any step $i \in [2,k]$, we have
\begin{equation}
\bar{C}(y_i;i) := \sup_{X_{i-1},\theta}\int p(y_i \mid X_i,\theta)p(X_i \mid X_{i-1},\theta)dX_i < \infty.
\label{ieq:assumption_z}
\end{equation}
The total variation distance between $p(X_k,\theta \mid \Y_k)$ and $q_k(X_k,\theta)$, namely $d_{TV}(p(X_k,\theta \mid \Y_k), q_k(X_k,\theta))$, satisfies:
\begin{align}
d_{TV}\left(p(X_k,\theta \mid \Y_k), q_k(X_k,\theta)\right) &\leq \sum_{j=1}^{k-1}\frac{\prod_{i=j+1}^k\bar{C}(y_i;i)}{\prod_{i=j+1}^k \tilde{Z}_i(q_{i-1})}d_{TV}\left(q_j, q_j^*\right) + d_{TV}\left(q_k, q_k^*\right).
\end{align}
The Hellinger distance between $p(X_k,\theta \mid \Y_k)$ and $q_k(X_k,\theta)$, namely $d_{H}(p(X_k,\theta \mid \Y_k), q_k(X_k,\theta))$, satisfies:
\begin{align}
d_{H}(p(X_k,\theta \mid \Y_k), q_k(X_k,\theta)) &\leq \sum_{j=1}^{k-1}\frac{2^{(k-j)}\prod_{i=j+1}^k\sqrt{\bar{C}(y_i;i)}}{\prod_{i=j+1}^k\sqrt{ \tilde{Z}_i(q_{i-1})}}d_{H}\left(q_j, q_j^*\right) + d_{H}\left(q_k, q_k^*\right).
\end{align}
Here $\tilde{Z}_i(q_{i-1})$ is defined as $\tilde{Z}_i(q_{i-1}):= \int p(y_i \mid X_i,\theta)p(X_i \mid X_{i-1},\theta)q_{i-1}(X_{i-1},\theta)dX_{i-1}dX_id\theta$.
\end{theorem}
Next, we provide the proof of Theorem~\ref{thm:error_bound_linear}.
\begin{proof}
In the proof of Theorem~\ref{thm:error_bound}, we showed that the assumption in Theorem~\ref{thm:learning_bound_z} holds under the condition $\inf_{\theta} \lvert \Gamma(\theta) \rvert = \tilde{C} > 0$. Here $\bar{C}(y_i; i)$ satisfies 
\begin{equation}
\bar{C}(y_i;i) \leq (2\pi)^{-\frac{r}{2}}\tilde{C}^{-\frac{1}{2}}.
\label{eq:C_thm2}
\end{equation}
Next, we prove that $\tilde{Z}_i(q_{i-1})= \E_{\theta \sim \nu_{i-1}(\cdot)}[\pdense_{\mathcal{N}}(y_i;H(\theta)m_i^{*-}(\theta), H(\theta)C_i^{*-}(\theta)H(\theta)^T+\Gamma(\theta))]$. According to the definition of $\tilde{Z}_{i}(q_{i-1})$, it can be written as 
\begin{align}
\tilde{Z}_{i}(q_{i-1}) &= \int p_\mathcal{N}(y_i; H(\theta)X_i, \Gamma(\theta))p_\mathcal{N}(X_i; A(\theta)X_{i-1},\Sigma(\theta))p_\mathcal{N}(X_{i-1};m_{i-1}(\theta), C_{i-1}(\theta))\nu_{i-1}(\theta)dX_{i-1}dX_id\theta \nonumber \\
&= \E_{\theta \sim \nu_{i-1}(\cdot)}\left[\int p_\mathcal{N}(y_i; H(\theta)X_i, \Gamma(\theta))p_\mathcal{N}(X_i; A(\theta)X_{i-1},\Sigma(\theta))p_\mathcal{N}(X_{i-1};m_{i-1}(\theta), C_{i-1}(\theta))dX_{i-1}dX_i\right] \nonumber \\
&= \E_{\theta \sim \nu_{i-1}(\cdot)}[\pdense_{\mathcal{N}}(y_i;H(\theta)m_i^{*-}(\theta), H(\theta)C_i^{*-}(\theta)H(\theta)^T+\Gamma(\theta))].
\label{eq:z}
\end{align}
By Equations~\eqref{ieq:vi:type1:tv_approx} and ~\eqref{ieq:vi:type1:H_approx}, the terms $d_{TV}(q_j,q_j^*)$ and $d_{H}(q_j,q_j^*)$ satisfy
\begin{align}
d_{TV}(q_j,q_j^*) & \leq \frac{1} {\sqrt{2}}\sqrt{\KL\left(q_j \lVert q^*_j\right)} = \frac{1}{\sqrt{2}}\sqrt{\E_{\theta \sim \nu_j(\cdot)}\left[\KL\left(\rho_j(\cdot\mid \theta) \lVert \rho_j^*(\cdot \mid \theta) \right) \right] +\KL\left(\nu_j \lVert \nu_j^*\right)},
\label{ieq:vi:type1:tv_approx_2}
\end{align}
and
\begin{align}
d_{H}(q_j,q_j^*) & \leq \frac{1}{\sqrt{2}}\sqrt{\KL\left(q_j \lVert q^*_j\right)} = \frac{1}{\sqrt{2}}\sqrt{\E_{\theta \sim \nu_j(\cdot)}\left[\KL\left(\rho_j(\cdot \mid \theta) \lVert \rho_j^*(\cdot \mid \theta) \right) \right] +\KL\left(\nu_j \lVert \nu_j^*\right)}.
\label{ieq:vi:type1:H_approx_2}
\end{align}
According to Equations~\eqref{eq:nu_star},~\eqref{eq:kl_step1} and~\eqref{eq:elbo_step1}, the KL divergence $\KL\left(\nu_j \lVert \nu_j^*\right)$ can be written as
\begin{equation*}
\KL\left(\nu_j \lVert \nu_j^*\right) = \log \hat{Z}_j - \mathcal{L}_j(\nu_j),
\end{equation*}
where 
\begin{equation*}
\hat{Z}_j =  \int \pdense_\mathcal{N}(y_j; h(X_j;\theta), \Gamma(\theta))\, \rho_j^{*-}(X_j \mid \theta)\,\nu_{j-1}(\theta)dX_jd\theta.
\end{equation*}
Recall that the probability density $\pdense_\mathcal{N}(y_j; h(X_j;\theta), \Gamma(\theta))$
satisfies
\begin{align*}
\pdense_\mathcal{N}(y_j; h(X_j;\theta), \Gamma(\theta)) \leq (2\pi)^{-\frac{r}{2}}\tilde{C}^{-\frac{1}{2}}, \quad \forall X_j, \theta
\end{align*}
The KL divergence $\KL\left(\nu_j \lVert \nu_j^*\right)$ satisfies
\begin{align}
\KL(\nu_j  \| \nu_j^*) 
&\leq \log \left((2\pi)^{-\frac{r}{2}}\tilde{C}^{-\frac{1}{2}}\int \rho_j^{*-}(X_j \mid \theta)\nu_{j-1}(\theta) \, dX_jd\theta \right) - \mathcal{L}_j(\nu_j) \nonumber \\
& =\log \left((2\pi)^{-\frac{r}{2}}\tilde{C}^{-\frac{1}{2}}\right) - \mathcal{L}_j(\nu_j) \nonumber \\
& \leq -\frac{r}{2}\log(2\pi) - \frac{1}{2}\log \tilde{C} - \epsilon_j.
\label{ieq:kl_theta}
\end{align}

We next derive the expression of the KL divergence $\KL\left(\rho_j(\cdot \mid \theta) \lVert \rho_j^*(\cdot \mid \theta) \right)$.
The analytical expression of $\rho_j^*(X_j \mid \theta)$ is given by Kalman filter:
\begin{equation}
\rho_j^*(X_j \mid \theta) = \pdense_{\mathcal{N}}\bigg (X_j; F_m(m_{j-1}(\theta), C_{j-1}(\theta),\theta), F_c(m_{j-1}(\theta), C_{j-1}(\theta),\theta)\bigg).
\end{equation}
Recall that $\rho_j(X_j \mid \theta) = \pdense_{\mathcal{N}}(X_j; m_j(\theta), C_j(\theta))$. By employing the formula for the KL divergence of one Gaussian distribution with respect to another Gaussian distribution, we obtain
\begin{equation}
\KL\left(\rho_j(\cdot \mid \theta) \lVert \rho_j^*(\cdot \mid \theta) \right) = \Psi_j(C_j(\theta), m_j(\theta), C_{j-1}(\theta), m_{j-1}(\theta), \theta). 
\label{eq:kl_state}
\end{equation}
Finally, combining Equations~\eqref{eq:C_thm2},~\eqref{eq:z}, \eqref{ieq:vi:type1:tv_approx_2}, \eqref{ieq:vi:type1:H_approx_2}, \eqref{ieq:kl_theta}, and \eqref{eq:kl_state}, together with Theorem~\ref{thm:learning_bound_z}, completes the proof.
\end{proof}

\label{sec:step1_eg1}
When a non-Gaussian distribution is used to represent $\rho_k(X_k \mid \theta)$, the following procedure can be applied to compute the integral $I(\theta)$ in Equation~\eqref{eq:elbo_step1}, for evaluating the ELBO $\mathcal{L}_k(\nu_k)$.  

For a given $\theta$, draw $N$ samples from the previous conditional distribution $\rho_{k-1}(X_{k-1} \mid \theta)$ and $N$ samples of the process noise:
\begin{equation*}
X_{k-1}^{(i)} \overset{\mathrm{i.i.d.}}{\sim} \rho_{k-1}(X_{k-1} \mid \theta), \qquad 
\xi^{(i)} \overset{\mathrm{i.i.d.}}{\sim} \mathcal{N}(0,\Sigma(\theta)). 
\end{equation*}
The samples of the predictive distribution $\rho_k^{*-}(X_k \mid \theta)$ can then be constructed by
\begin{equation*}
X_k^{(i)-} = \Phi(X_{k-1}^{(i)};\theta) + \xi^{(i)}.
\end{equation*}
As a result, the integral 
\(I(\theta)\) can be approximated by
\begin{equation}
I(\theta)
\approx \frac{1}{N}\sum_{i=1}^N \pdense_{\mathcal{N}}(y_k;h(X_k^{(i)-};\theta), \Gamma(\theta)).
\label{eq:elbo_eg1}
\end{equation}

Following Stage 1, we first employ a filtering method to approximate the online conditional filtering distribution $\rho_k^*(X_k \mid \theta)$ with a distribution $\hat{\rho}_k(X_k \mid \theta)$. The parametric family used to represent $\rho_k(X_k \mid \theta)$ is chosen to be the same with that of $\hat{\rho}_k(X_k \mid \theta)$. Let $\phi_k(\theta)$ and $\phi_k^*(\theta)$ denote the corresponding hyperparameters used to represent the distributions $\rho_k(X_k \mid \theta)$ and $\hat{\rho}_k(X_k \mid \theta)$, respectively. If we directly set $\rho_k(X_k \mid \theta) = \hat{\rho}_k(X_k \mid \theta)$, i.e., $\phi_k(\theta) = \phi_k^*(\theta)$, then the complexity of the functional representation of $\phi_k(\theta)$ will grow with time step $k$. To maintain constant computational and storage costs over time, we therefore re-approximate $\hat{\rho}(X_k \mid \theta)$ with $\rho(X_k \mid \theta)$ by minimizing the expected KL divergence $\E_{\theta \sim \nu_k(\cdot)}[\KL\left(\rho_k(\cdot \mid \theta) \lVert \hat{\rho}_k(\cdot \mid \theta)\right)]$. For a given $\theta$, the KL divergence $\KL\left(\rho_k(\cdot \mid \theta) \lVert \hat{\rho}_k(\cdot \mid \theta)\right)$ can be approximated using the Monte Carlo method with samples generated from $\rho_k(X_k \mid \theta)$:
\begin{equation*}
\KL\left(\rho_k(\cdot \mid \theta) \lVert \hat{\rho}_k(\cdot \mid \theta)\right) \approx \frac{1}{N_x}\sum_{i=1}^{N_x} \left(\log \rho_k(X_k^{(i)} \mid \theta) - \log \hat{\rho}_k(X_k^{(i)} \mid \theta) \right), \qquad X_k^{(i)} \overset{\mathrm{i.i.d.}}{\sim} \rho_k(\cdot \mid \theta).
\end{equation*}  
When computational resources are highly constrained, the training loss can be simplified to  
\begin{equation*}
\frac{1}{N_{\theta}}\sum_{i=1}^{N_{\theta}} \big\lVert \phi_k(\theta^{(i)}) - \phi_k^*(\theta^{(i)}) \big\rVert_2^2, 
\qquad \theta^{(i)} \overset{\mathrm{i.i.d.}}{\sim} \nu_k(\cdot).
\end{equation*}
Finally, the distribution $\nu_k(\theta)$ together with the function $\phi_k(\theta)$ are passed forward to the next time step $k+1$.

\label{sec:nonlinear_observations}
In this section, we consider a nonlinear single pendulum with a nonlinear observation model. The dynamics of the single pendulum are described by
\begin{equation}
\begin{bmatrix}
\dot{x}_1 \\ \dot{x}_2 
\end{bmatrix}
=
\begin{bmatrix}
x_2 \\
-\frac{g}{l}\sin(x_1)
\end{bmatrix},
\label{eq:nonlinear_pendulum}
\end{equation}
where $g=9.8$ denotes the gravitational acceleration and $l=1.2$ denotes the length of the pendulum~\cite{fbovi}. The initial state is $x_1(0)=0.5$ and $x_2(0)=0.5$. We use the forward Euler method to integrate Equation~\eqref{eq:nonlinear_pendulum} with time discretization interval $\Delta t=0.1$ and generate the reference trajectory for $50$ time steps. The resulting discrete-time dynamics are
\begin{equation}
\begin{bmatrix}
x_1(k) \\ x_2(k) 
\end{bmatrix}
=
\begin{bmatrix}
x_1(k-1)+x_2(k-1)\Delta t \\
x_2(k-1)-\frac{g}{l}\sin(x_1(k-1))\Delta t
\end{bmatrix},
\end{equation}
where $x_1(k)$ and $x_2(k)$ denote the values of the state components $x_1$ and $x_2$ at time step $k$, respectively. Using this reference trajectory, we generate the data according to the following nonlinear observation model
\begin{equation}
Y_k = \sqrt[3]{x_1(k)} + V_k, \quad V_k \sim \mathcal{N}(0, 0.01).
\label{eq:nonlinear_pendulum_obs}
\end{equation}

We assume that the observation model is known and seek to learn a stochastic dynamical model and the state of the pendulum. The dynamical model is parameterized as follows:
\begin{equation*}
\begin{bmatrix}
x_1(k) \\ x_2(k) 
\end{bmatrix}
=
\begin{bmatrix}
\theta_1 x_1(k-1)+x_2(k-1)\Delta t \\
\theta_1 x_2(k-1)-\theta_2\sin(x_1(k-1))
\end{bmatrix}
+
W_k, 
\quad
W_k \sim \mathcal{N}(0,0.01I_{2\times 2}),
\end{equation*}
where $\theta=(\theta_1,\theta_2)$ are unknown model parameters and $\Delta t=0.1$ is known. The priors for $\theta$ and the initial state are $\mathcal{N}(\mathbf{0},I_{2\times 2})$ and $\mathcal{N}([3,4.5]^T,4I_{2\times 2})$, respectively. The prior mean of the initial state is far from the true value, making the inference problem challenging.

We compare the results of FBOVI for the nonlinear observation model~\eqref{eq:nonlinear_pendulum_obs} with the results for the linear observation model
\begin{equation}
Y_k = x_1(k) + V_k, \quad V_k \sim \mathcal{N}(0,0.01).
\label{eq:linear_pendulum_obs}
\end{equation}
The reference state trajectory, dynamical model, parameter prior, and initial-state prior are kept the same across the tests with the two observation models. The results of FBOVI for the linear observation model~\eqref{eq:linear_pendulum_obs} were presented in our previous work~\cite{fbovi}.

Figure~\ref{fig:nonlinearObservations} depicts the marginal posterior distributions of the parameters and state components obtained by FBOVI at different time steps for the observation models~\eqref{eq:linear_pendulum_obs} and~\eqref{eq:nonlinear_pendulum_obs}. The results show that FBOVI successfully infers the parameters and state in both cases. The learning performance for $\theta_2$ in the case with the nonlinear observation model~\eqref{eq:nonlinear_pendulum_obs} is slightly worse than that in the case with the linear observation model~\eqref{eq:linear_pendulum_obs}. Apart from this difference, FBOVI provides accurate estimation of $\theta_1$ after step $20$ in both cases and rapidly starts tracking the true state values closely under both observation models.

